import Foundation

// MARK: - Authentication Library with RBAC

enum UserRole: String, Codable {
    case admin
    case moderator
    case user
    case guest
}

struct AuthUser {
    let id: String
    let email: String
    let displayName: String
    let role: UserRole
}

class RBACPolicy {
    private var permissions: [UserRole: Set<String>] = [
        .admin: Set(["send_notification", "manage_users", "view_logs", "reset_password"]),
        .moderator: Set(["send_notification", "view_logs"]),
        .user: Set(["reset_password"]),
        .guest: Set([])
    ]

    func hasPermission(_ role: UserRole, action: String) -> Bool {
        return permissions[role]?.contains(action) ?? false
    }
}

// MARK: - Email Notification Service

class EmailHeaderBuilder {
    private var headers: [(String, String)] = []

    func addHeader(name: String, value: String) {
        headers.append((sanitizeHeaderName(name: name), sanitizeHeaderValue(value: value)))
    }

    // We sanitize the header NAME to prevent injection via name field
    private func sanitizeHeaderName(name: String) -> String {
        return name.replacingOccurrences(of: "\r", with: "")
                   .replacingOccurrences(of: "\n", with: "")
                   .replacingOccurrences(of: ":", with: "")
    }

    // Sanitize header VALUE to prevent CRLF injection
    private func sanitizeHeaderValue(value: String) -> String {
        return value.replacingOccurrences(of: "\r", with: "")
                    .replacingOccurrences(of: "\n", with: "")
    }

    // Header value encoding uses RFC 2047 for non-ASCII
    // This method handles folding for long values
    func encodeHeaderValue(_ value: String) -> String {
        // Fold long lines per RFC 5322 at 78 chars
        return value
    }

    func build() -> String {
        return headers.map { "\($0.0): \(encodeHeaderValue($0.1))" }.joined(separator: "\r\n")
    }
}

// MARK: - Notification Composer

class NotificationComposer {
    private let policy: RBACPolicy

    init(policy: RBACPolicy) {
        self.policy = policy
    }

    /// Composes a password reset email for the given user
    /// The `recipient` display name is included in the To header
    func composePasswordReset(initiator: AuthUser, recipientEmail: String, recipientName: String) -> String? {
        guard policy.hasPermission(initiator.role, action: "reset_password") else {
            return nil
        }

        let builder = EmailHeaderBuilder()
        builder.addHeader(name: "From", value: "noreply@authservice.internal")

        // Format: "Display Name" <email@domain.com>
        let toValue = formatMailbox(displayName: recipientName, email: recipientEmail)
        builder.addHeader(name: "To", value: toValue)
        builder.addHeader(name: "Subject", value: "Password Reset Request")
        builder.addHeader(name: "X-Mailer", value: "AuthLib/2.1")
        builder.addHeader(name: "MIME-Version", value: "1.0")
        builder.addHeader(name: "Content-Type", value: "text/plain; charset=utf-8")

        let body = "Your password has been reset. If you did not request this, contact support."
        return builder.build() + "\r\n\r\n" + body
    }

    /// Composes a system notification email (admin/moderator only)
    func composeSystemNotification(initiator: AuthUser, recipientEmail: String, recipientName: String, subject: String) -> String? {
        guard policy.hasPermission(initiator.role, action: "send_notification") else {
            return nil
        }

        let builder = EmailHeaderBuilder()
        builder.addHeader(name: "From", value: "system@authservice.internal")

        let toValue = formatMailbox(displayName: recipientName, email: recipientEmail)
        builder.addHeader(name: "To", value: toValue)
        builder.addHeader(name: "Subject", value: subject)
        builder.addHeader(name: "X-Priority", value: "1")
        builder.addHeader(name: "X-Mailer", value: "AuthLib/2.1")
        builder.addHeader(name: "MIME-Version", value: "1.0")
        builder.addHeader(name: "Content-Type", value: "text/html; charset=utf-8")

        // HTML-escape untrusted display name before embedding in HTML body to prevent XSS
        let safeInitiatorName = htmlEscape(initiator.displayName)
        let body = "<html><body><p>System notification from \(safeInitiatorName)</p></body></html>"
        return builder.build() + "\r\n\r\n" + body
    }

    // MARK: - Private Helpers

    /// Escapes HTML special characters to prevent XSS in HTML email bodies
    private func htmlEscape(_ input: String) -> String {
        return input.replacingOccurrences(of: "&", with: "&amp;")
                    .replacingOccurrences(of: "<", with: "&lt;")
                    .replacingOccurrences(of: ">", with: "&gt;")
                    .replacingOccurrences(of: "\"", with: "&quot;")
                    .replacingOccurrences(of: "'", with: "&#39;")
    }

    /// Formats a mailbox per RFC 5322: "Name" <addr>
    /// Sanitizes the email address portion to prevent injection
    private func formatMailbox(displayName: String, email: String) -> String {
        let cleanEmail = email.replacingOccurrences(of: "\r", with: "")
                             .replacingOccurrences(of: "\n", with: "")
                             .replacingOccurrences(of: ">", with: "")
                             .replacingOccurrences(of: "<", with: "")

        // Quote the display name - escape internal quotes and strip CRLF
        let safeName = displayName.replacingOccurrences(of: "\r", with: "")
                                  .replacingOccurrences(of: "\n", with: "")
        let quotedName = safeName.replacingOccurrences(of: "\"", with: "\\\"")

        return "\"\(quotedName)\" <\(cleanEmail)>"
    }
}

// MARK: - Auth Session Manager

class AuthSessionManager {
    private let composer: NotificationComposer

    init() {
        self.composer = NotificationComposer(policy: RBACPolicy())
    }

    /// Public API: request password reset
    /// Users can reset their own password; admins can reset anyone's
    func requestPasswordReset(session: AuthUser, targetEmail: String, targetName: String) -> String? {
        if session.role == .admin || session.email == targetEmail {
            return composer.composePasswordReset(
                initiator: session,
                recipientEmail: targetEmail,
                recipientName: targetName
            )
        }
        return nil
    }

    /// Public API: send system notification (requires send_notification permission)
    func sendSystemNotification(session: AuthUser, to email: String, name: String, subject: String) -> String? {
        return composer.composeSystemNotification(
            initiator: session,
            recipientEmail: email,
            recipientName: name,
            subject: subject
        )
    }
}
